/**
* @brief  This function handles I2C Communication Timeout for specific usage of RXNE flag.
* @param  hi2c Pointer to a I2C_HandleTypeDef structure that contains
*                the configuration information for the specified I2C.
* @param  Timeout Timeout duration
* @param  Tickstart Tick start value
* @retval HAL status
*/
static HAL_StatusTypeDef I2C_WaitOnRXNEFlagUntilTimeout(I2C_HandleTypeDef *hi2c, uint32_t Timeout, uint32_t Tickstart)
{
  /* In emulation, we don't wait for hardware flags */
  /* Just check for timeout to preserve the timeout logic */
  if (((HAL_GetTick() - Tickstart) > Timeout) || (Timeout == 0U))
  {
    hi2c->PreviousState       = I2C_STATE_NONE;
    hi2c->State               = HAL_I2C_STATE_READY;
    hi2c->Mode                = HAL_I2C_MODE_NONE;
    hi2c->ErrorCode           |= HAL_I2C_ERROR_TIMEOUT;

    /* Process Unlocked */
    __HAL_UNLOCK(hi2c);

    return HAL_ERROR;
  }

  /* For emulation, we assume the flag condition is immediately met */
  /* This avoids infinite loops waiting for hardware that doesn't exist */
  return HAL_OK;
}
